/**
 * Spec-derived final-gate checks for web projects (generated by the Director, deterministic):
 * every page has the same shared nav, one shared stylesheet, no broken internal links, viewport
 * meta, binding design tokens; plus a hidden headless-Chromium pass (console errors, phone
 * overflow, screenshots at mobile + desktop sizes) when Playwright is installed.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';

export const WEB_SITE_CHECK_PATH = '.ai-manager/checks/web-site-check.cjs';
export const WEB_BROWSER_CHECK_PATH = '.ai-manager/checks/web-browser-check.cjs';
export const SCREENSHOT_DIR = path.join('.ai-manager', 'reports', 'screenshots');

const SKIP = new Set(['node_modules', '.git', '.ai-manager', 'dist', 'build', 'coverage']);
export function listHtmlPages(root: string): string[] {
  const out: string[] = [];
  const walk = (d: string) => {
    let entries: fs.Dirent[] = [];
    try { entries = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (SKIP.has(e.name) || e.name.startsWith('.')) continue;
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (/\.html?$/i.test(e.name)) out.push(path.relative(root, p).split(path.sep).join('/'));
    }
  };
  walk(root);
  return out.sort();
}

/** Writes the check scripts into the project and returns the gate commands (empty for non-web projects). */
export function webGateCommands(root: string, opts: { browser?: boolean } = {}): string[] {
  if (!listHtmlPages(root).length) return [];
  const dir = path.join(root, '.ai-manager', 'checks');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(root, WEB_SITE_CHECK_PATH), WEB_SITE_CHECK_JS);
  const cmds = [`node ${WEB_SITE_CHECK_PATH}`];
  if (opts.browser !== false) {
    fs.writeFileSync(path.join(root, WEB_BROWSER_CHECK_PATH), WEB_BROWSER_CHECK_JS);
    cmds.push(`node ${WEB_BROWSER_CHECK_PATH}`);
  }
  return cmds;
}

export interface BrowserCheckResult { available: boolean; pages: string[]; screenshots: { file: string; page: string; view: string }[]; consoleErrors: string[] }
export function readBrowserCheck(root: string): BrowserCheckResult | null {
  try { return JSON.parse(fs.readFileSync(path.join(root, SCREENSHOT_DIR, 'browser-check.json'), 'utf8')) as BrowserCheckResult; } catch { return null; }
}

export const WEB_SITE_CHECK_JS = String.raw`// aidm web site check (auto-generated by the Director; deterministic, no dependencies).
'use strict';
const fs = require('fs');
const path = require('path');
const root = process.cwd();
const SKIP = new Set(['node_modules', '.git', '.ai-manager', 'dist', 'build', 'coverage']);
const fails = [];
const ok = [];
function walk(d, out) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (SKIP.has(e.name) || e.name.startsWith('.')) continue;
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p, out);
    else out.push(path.relative(root, p).split(path.sep).join('/'));
  }
  return out;
}
const files = walk(root, []);
const pages = files.filter((f) => /\.html?$/i.test(f));
if (!pages.length) { console.log('WEB CHECK: no HTML pages found'); process.exit(1); }
const read = (f) => fs.readFileSync(path.join(root, f), 'utf8');
const attr = (tag, name) => { const m = new RegExp('\\b' + name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i').exec(tag); return m ? (m[2] ?? m[3] ?? m[4] ?? '') : null; };
const isLocal = (u) => u && !/^(?:[a-z][a-z0-9+.-]*:|\/\/|#|\{\{)/i.test(u);
const navSig = {};
const cssOf = {};
for (const p of pages) {
  const html = read(p);
  const dir = path.posix.dirname(p);
  // viewport (mobile)
  if (!/<meta[^>]+name\s*=\s*["']?viewport/i.test(html)) fails.push(p + ': viewport meta etiketi yok (telefonda düzgün görünmez)');
  // shared nav
  const nav = /<nav\b[\s\S]*?<\/nav>/i.exec(html);
  if (!nav) fails.push(p + ': ortak gezinme menüsü (<nav>) yok');
  else navSig[p] = (nav[0].match(/<a\b[^>]*>/gi) || []).map((a) => attr(a, 'href') || '').map((h) => path.posix.normalize(path.posix.join(dir, h.split('#')[0].split('?')[0] || path.posix.basename(p)))).sort().join('|');
  // stylesheets
  cssOf[p] = (html.match(/<link\b[^>]*>/gi) || []).filter((l) => /stylesheet/i.test(attr(l, 'rel') || '')).map((l) => attr(l, 'href')).filter(isLocal).map((h) => path.posix.normalize(path.posix.join(dir, h.split('?')[0])));
  // internal links / assets
  const refs = [];
  for (const t of html.match(/<(a|link|script|img|source|iframe)\b[^>]*>/gi) || []) {
    for (const a of ['href', 'src']) { const v = attr(t, a); if (isLocal(v)) refs.push(v); }
    const ss = attr(t, 'srcset'); if (ss) for (const part of ss.split(',')) { const u = part.trim().split(/\s+/)[0]; if (isLocal(u)) refs.push(u); }
  }
  for (const r of refs) {
    const clean = decodeURI(r.split('#')[0].split('?')[0]);
    if (!clean) continue;
    let target = clean.startsWith('/') ? clean.slice(1) : path.posix.normalize(path.posix.join(dir, clean));
    if (target.endsWith('/') || target === '.') target = path.posix.join(target, 'index.html');
    if (!fs.existsSync(path.join(root, target))) fails.push(p + ': kırık iç bağlantı → ' + r);
  }
}
// same nav everywhere
const sigs = Object.values(navSig);
if (sigs.length > 1 && new Set(sigs).size > 1) fails.push('Sayfalardaki gezinme menüleri aynı değil: ' + Object.entries(navSig).map(([k, v]) => k + ' [' + v.split('|').length + ' bağlantı]').join(', '));
// single shared stylesheet
const lists = Object.values(cssOf);
const common = lists.length ? lists.reduce((a, b) => a.filter((x) => b.includes(x))) : [];
if (!common.length) fails.push('Tüm sayfaların kullandığı tek bir ortak CSS dosyası yok');
const allCss = new Set(lists.flat());
const css = files.filter((f) => /\.css$/i.test(f));
// design tokens (binding design brief)
const briefFile = path.join(root, '.ai-manager', 'state', 'design-brief.json');
if (fs.existsSync(briefFile)) {
  try {
    const brief = JSON.parse(fs.readFileSync(briefFile, 'utf8'));
    const text = css.map(read).join('\n').replace(/\s+/g, '');
    for (const [k, v] of Object.entries(brief.tokens || {})) {
      const want = ('--' + k + ':' + String(v)).replace(/\s+/g, '');
      if (!text.toLowerCase().includes(want.toLowerCase())) fails.push('Tasarım token eksik/farklı: --' + k + ': ' + v);
    }
  } catch (e) { fails.push('design-brief.json okunamadı: ' + e.message); }
}
ok.push(pages.length + ' sayfa', 'ortak CSS: ' + (common.join(', ') || '-'), 'CSS dosyası: ' + allCss.size);
if (fails.length) { console.log('WEB CHECK FAIL (' + fails.length + '):\n- ' + fails.join('\n- ')); process.exit(1); }
console.log('WEB CHECK PASS: ' + ok.join('; '));
`;

export const WEB_BROWSER_CHECK_JS = String.raw`// aidm browser check: hidden headless Chromium; console errors + screenshots (mobile, desktop).
'use strict';
const fs = require('fs');
const path = require('path');
const http = require('http');
const { createRequire } = require('module');
const root = process.cwd();
const outDir = path.join(root, '.ai-manager', 'reports', 'screenshots');
const SKIP = new Set(['node_modules', '.git', '.ai-manager', 'dist', 'build', 'coverage']);
function walk(d, out) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (SKIP.has(e.name) || e.name.startsWith('.')) continue;
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p, out); else if (/\.html?$/i.test(e.name)) out.push(path.relative(root, p).split(path.sep).join('/'));
  }
  return out;
}
function loadPlaywright() {
  const dirs = [process.env.AIDM_PLAYWRIGHT_DIR, process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'aidm', 'browser'), process.env.HOME && path.join(process.env.HOME, '.aidm', 'browser'), root].filter(Boolean);
  for (const d of dirs) { try { return createRequire(path.join(d, 'package.json'))('playwright'); } catch (e) { /* next */ } }
  return null;
}
const TYPES = { '.html': 'text/html; charset=utf-8', '.htm': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.mjs': 'text/javascript', '.json': 'application/json', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.gif': 'image/gif', '.ico': 'image/x-icon', '.woff2': 'font/woff2', '.woff': 'font/woff' };
async function main() {
  const pages = walk(root, []);
  fs.mkdirSync(outDir, { recursive: true });
  const pw = loadPlaywright();
  const result = { available: !!pw, pages: [], screenshots: [], consoleErrors: [] };
  if (!pw) {
    fs.writeFileSync(path.join(outDir, 'browser-check.json'), JSON.stringify(result, null, 2));
    console.log('BROWSER CHECK SKIPPED: Playwright/Chromium kurulu değil (AIDM_PLAYWRIGHT_DIR). Konsol hataları ve ekran görüntüleri kontrol edilmedi.');
    process.exit(Number(process.env.AIDM_BROWSER_REQUIRED === '1'));
  }
  const server = http.createServer((req, res) => {
    let u = decodeURIComponent((req.url || '/').split('?')[0]);
    if (u.endsWith('/')) u += 'index.html';
    const f = path.join(root, path.normalize(u).replace(/^([/\\])+/, ''));
    if (!f.startsWith(root) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) { res.writeHead(404); res.end('not found'); return; }
    res.writeHead(200, { 'content-type': TYPES[path.extname(f).toLowerCase()] || 'application/octet-stream' });
    fs.createReadStream(f).pipe(res);
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const base = 'http://127.0.0.1:' + server.address().port + '/';
  const browser = await pw.chromium.launch({ headless: true });
  const views = [{ id: 'mobil', width: 390, height: 844, mobile: true }, { id: 'masaustu', width: 1366, height: 900, mobile: false }];
  try {
    for (const p of pages) {
      for (const v of views) {
        const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, isMobile: v.mobile, hasTouch: v.mobile, deviceScaleFactor: 1 });
        const page = await ctx.newPage();
        const errs = [];
        page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
        page.on('pageerror', (e) => errs.push(String(e && e.message || e)));
        page.on('response', (r) => { if (r.status() >= 400 && r.url().startsWith(base)) errs.push('HTTP ' + r.status() + ' ' + r.url().slice(base.length)); });
        await page.goto(base + p, { waitUntil: 'load', timeout: 30000 }).catch((e) => errs.push('yüklenemedi: ' + e.message));
        await page.waitForTimeout(500);
        const name = p.replace(/[^A-Za-z0-9._-]+/g, '_').replace(/\.html?$/i, '') + '-' + v.id + '.jpg';
        await page.screenshot({ path: path.join(outDir, name), type: 'jpeg', quality: 60, fullPage: false }).catch(() => {});
        // overflow on mobile = layout breaks on phones
        if (v.mobile) {
          const over = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
          if (over > 4) errs.push('telefonda yatay taşma: ' + over + 'px');
        }
        result.screenshots.push({ file: name, page: p, view: v.id });
        for (const e of errs) result.consoleErrors.push(p + ' (' + v.id + '): ' + e);
        await ctx.close();
      }
      result.pages.push(p);
    }
  } finally {
    await browser.close();
    server.close();
  }
  fs.writeFileSync(path.join(outDir, 'browser-check.json'), JSON.stringify(result, null, 2));
  if (result.consoleErrors.length) { console.log('BROWSER CHECK FAIL:\n- ' + result.consoleErrors.slice(0, 40).join('\n- ')); process.exit(1); }
  console.log('BROWSER CHECK PASS: ' + pages.length + ' sayfa, ' + result.screenshots.length + ' ekran görüntüsü, konsol hatası yok');
}
main().catch((e) => { console.log('BROWSER CHECK ERROR: ' + (e && e.message || e)); process.exit(1); });
`;
